values ('ap_chemistry', 8, '8.5', array['8.5', '8.9']::text[], 'vocabulary', 'Half-equivalence point and pKa', 'The point halfway to the equivalence point in a weak acid/base titration, where [HA] = [A−], so pH = pKa and the pKa can be read from the pH there.', '[]'::jsonb, NULL, 'Read pKa from the pH at the half-equivalence point, not from the pH at the equivalence point.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u8-r1-022; ced=8.5.A.3 pH = pKa when the conjugate acid and base have equal concentrations')
