values ('ap_chemistry', 8, '8.6', array['8.6']::text[], 'convention', 'Structure and acid/base strength', 'Strong acids have very weak conjugate bases stabilized by electronegativity, inductive effects, resonance, or a combination; strong bases have very weak conjugate acids; electronegative elements stabilize the conjugate base and increase acid strength.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u8-r1-025; ced=8.6.A.1 Electronegative elements tend to stabilize the conjugate base relative to the conjugate acid')
