values ('ap_chemistry', 8, '8.7', array['8.7', '8.9']::text[], 'convention', 'Predominant form: compare pH to pKa', 'When pH < pKa the acid form (HA) has the higher concentration; when pH > pKa the base form (A−) has the higher concentration.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u8-r1-027; ced=8.7.A.1 When solution pH < acid pKa, the acid form has a higher concentration')
