insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 8, '8.9', array['8.9']::text[], 'convention', 'Why small additions barely change buffer pH', 'Adding small amounts of acid or base does not significantly change the ratio [A−]/[HA], so the buffer''s pH changes much less than it would without the buffer.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u8-r2-013; ced=8.9.A.1 does not significantly change the ratio of [A−]/[HA]')
